if(!defined('VELTRION_RUNTIME_GUARD') && file_exists(__DIR__ . '/../bootstrap/guard.php')){ @include_once __DIR__ . '/../bootstrap/guard.php'; }
  class LicenseEngine { private string $projectRoot; private LicenseGenerator $generator; private LicenseValidator $validator; private MachineIdentity $machineIdentity; public function __construct(?string $projectRoot = null) { $this->projectRoot = $projectRoot ?? __DIR__ . '/../../../../'; $this->generator = new LicenseGenerator(); $this->machineIdentity = new MachineIdentity(); $this->validator = new LicenseValidator(null, $this->machineIdentity); } public function getLicensePath(): string { return $this->projectRoot . '/storage/license.json'; } public function loadInstalledLicense(): ?License { $path = $this->getLicensePath(); if (!file_exists($path)) { return null; } $data = json_decode(file_get_contents($path), true); if (!$data) return null; return License::fromArray($data); } public function installLicense(string $licenseJsonPath): array { if (!file_exists($licenseJsonPath)) { return ['success' => false, 'error' => "Archivo de licencia no encontrado en {$licenseJsonPath}"]; } $data = json_decode(file_get_contents($licenseJsonPath), true); if (!$data) { return ['success' => false, 'error' => 'Formato JSON de licencia inválido']; } $license = License::fromArray($data); $validated = $this->validator->validateLicense($license); if (!$validated->isValid()) { return [ 'success' => false, 'status' => $validated->status, 'error' => "La licencia no es válida. Estado: {$validated->status}" ]; } $targetPath = $this->getLicensePath(); $dir = dirname($targetPath); if (!is_dir($dir)) mkdir($dir, 0777, true); file_put_contents($targetPath, json_encode($validated->toSignedArray(), JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE)); return [ 'success' => true, 'status' => 'INSTALLED', 'license_id' => $validated->licenseId, 'customer' => $validated->customerName, 'product' => $validated->productName, 'installed_at' => $targetPath ]; } public function inspectLicenseFile(string $licenseJsonPath): array { if (!file_exists($licenseJsonPath)) { return ['valid' => false, 'error' => 'Archivo no encontrado']; } $data = json_decode(file_get_contents($licenseJsonPath), true); if (!$data) { return ['valid' => false, 'error' => 'JSON inválido']; } $license = License::fromArray($data); $validated = $this->validator->validateLicense($license); return [ 'license' => $validated->toPayloadArray(), 'status' => $validated->status, 'is_valid' => $validated->isValid(), 'is_expired' => $validated->isExpired(), 'machine_id' => $this->machineIdentity->getMachineId(), 'signature' => $validated->signature ]; } public function createAndSaveLicense( string $productName, string $customerName, string $licenseType = License::TYPE_FULL, ?string $expirationDate = null, array $features = ['*'], ?string $machineBinding = null, string $outputPath = '' ): License { $license = $this->generator->createLicense( productName: $productName, customerName: $customerName, licenseType: $licenseType, expirationDate: $expirationDate, features: $features, machineBinding: $machineBinding ); if ($outputPath) { $dir = dirname($outputPath); if (!is_dir($dir)) mkdir($dir, 0777, true); file_put_contents($outputPath, json_encode($license->toSignedArray(), JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE)); } return $license; } public function revokeInstalledLicense(): bool { $path = $this->getLicensePath(); if (file_exists($path)) { return @unlink($path); } return true; } } 